<template>
  <div class="hanoi">
    <h2>Bài toán chuyển đĩa</h2>

    <div class="info">
      <label>
        Số đĩa:
        <select v-model.number="diskCount" @change="resetGame">
          <option v-for="n in [3,4,5,6,7]" :key="n" :value="n">
            {{ n }}
          </option>
        </select>
      </label>

      <span>Bước: {{ moves }}</span>
      <span>Tối thiểu: {{ minMoves }}</span>

      <button @click="resetGame">Reset</button>
    </div>

    <p v-if="isWon" class="win">
      🎉 Bạn đã thắng sau {{ moves }} bước!
    </p>

    <div class="stage-wrap">
      <v-stage :config="stageConfig">
        <v-layer>
          <v-group
            v-for="peg in pegs"
            :key="'peg-' + peg.id"
            :config="{ x: peg.x, y: baseY }"
          >
            <v-rect :config="baseConfig" />
            <v-rect :config="rodConfig" />
          </v-group>

          <v-group
            v-for="disk in disks"
            :key="disk.id + '-' + renderKey"
            :config="getDiskConfig(disk)"
            @dragstart="dragStart(disk)"
            @dragend="dragEnd(disk, $event)"
          >
            <v-rect :config="getDiskRect(disk)" />
            <v-text :config="getDiskText(disk)" />
          </v-group>
        </v-layer>
      </v-stage>
    </div>
  </div>
</template>

<script>
export default {
  name: 'ThapHaNoiPlus',

  data() {
    return {
      stageConfig: {
        width: 360,
        height: 460
      },

      baseY: 390,
      diskHeight: 24,
      diskCount: 4,

      // Đã chỉnh đĩa max nhỏ lại
      maxDiskWidth: 80,
      minDiskWidth: 30,

      disks: [],
      stacks: [[], [], []],

      moves: 0,
      fromPeg: null,
      renderKey: 0
    }
  },

  computed: {
    pegs() {
      const w = this.stageConfig.width

      return [
        { id: 0, x: w * 0.22 },
        { id: 1, x: w * 0.5 },
        { id: 2, x: w * 0.78 }
      ]
    },

    minMoves() {
      return Math.pow(2, this.diskCount) - 1
    },

    isWon() {
      return this.stacks[2].length === this.diskCount
    },

    baseConfig() {
      const isMobile = this.stageConfig.width < 480

      return {
        x: isMobile ? -50 : -90,
        y: 0,
        width: isMobile ? 100 : 180,
        height: 12,
        fill: '#334155',
        cornerRadius: 6
      }
    },

    rodConfig() {
      const isMobile = this.stageConfig.width < 480

      return {
        x: -5,
        y: isMobile ? -250 : -220,
        width: 10,
        height: isMobile ? 250 : 220,
        fill: '#475569',
        cornerRadius: 6
      }
    }
  },

  mounted() {
    this.resizeStage()
    window.addEventListener('resize', this.resizeStage)
    this.resetGame()
  },

  beforeDestroy() {
    window.removeEventListener('resize', this.resizeStage)
  },

  methods: {
    resizeStage() {
      const width = Math.min(window.innerWidth - 24, 800)

      this.stageConfig.width = Math.max(width, 320)

      if (this.stageConfig.width < 480) {
        this.stageConfig.height = 460
        this.baseY = 390
        this.diskHeight = 24

        // Mobile: đĩa nhỏ hơn
        this.maxDiskWidth = 80
        this.minDiskWidth = 30
      } else {
        this.stageConfig.height = 420
        this.baseY = 350
        this.diskHeight = 26

        // Desktop/tablet cũng giảm lại so với bản cũ
        this.maxDiskWidth = 180
        this.minDiskWidth = 60
      }

      this.$nextTick(() => {
        if (this.disks.length) this.layout()
      })
    },

    resetGame() {
      this.moves = 0
      this.fromPeg = null
      this.renderKey++

      this.stacks = [[], [], []]
      this.disks = []

      for (let size = this.diskCount; size >= 1; size--) {
        const id = 'disk-' + size

        this.stacks[0].push(id)

        this.disks.push({
          id,
          size,
          peg: 0,
          x: 0,
          y: 0,
          oldX: 0,
          oldY: 0
        })
      }

      this.layout()
    },

    layout() {
      this.stacks.forEach((stack, pegIndex) => {
        stack.forEach((diskId, level) => {
          const disk = this.disks.find(d => d.id === diskId)
          const peg = this.pegs[pegIndex]

          disk.peg = pegIndex
          disk.x = peg.x
          disk.y = this.baseY - this.diskHeight * (level + 1)

          disk.oldX = disk.x
          disk.oldY = disk.y
        })
      })

      this.renderKey++
    },

    getDiskWidth(disk) {
      const max = this.maxDiskWidth
      const min = this.minDiskWidth
      const step = (max - min) / (this.diskCount - 1)

      return min + (disk.size - 1) * step
    },

    getDiskConfig(disk) {
      return {
        x: Number(disk.x),
        y: Number(disk.y),
        draggable: !this.isWon && this.isTopDisk(disk)
      }
    },

    getDiskRect(disk) {
      const width = this.getDiskWidth(disk)

      return {
        x: -width / 2,
        y: 0,
        width,
        height: this.diskHeight,
        fill: this.getDiskColor(disk.size),
        stroke: '#ffffff',
        strokeWidth: 2,
        cornerRadius: 8
      }
    },

    getDiskText(disk) {
      return {
        x: -20,
        y: this.diskHeight / 2 - 7,
        width: 40,
        align: 'center',
        text: String(disk.size),
        fill: '#ffffff',
        fontSize: 14,
        fontStyle: 'bold'
      }
    },

    getDiskColor(size) {
      const colors = [
        '#ef4444',
        '#f97316',
        '#eab308',
        '#22c55e',
        '#06b6d4',
        '#3b82f6',
        '#8b5cf6'
      ]

      return colors[(size - 1) % colors.length]
    },

    isTopDisk(disk) {
      const stack = this.stacks[disk.peg]
      return stack[stack.length - 1] === disk.id
    },

    dragStart(disk) {
      if (!this.isTopDisk(disk) || this.isWon) return

      this.fromPeg = disk.peg
      disk.oldX = disk.x
      disk.oldY = disk.y
    },

    dragEnd(disk, e) {
      if (this.isWon) return

      const node = e.target
      const toPeg = this.getNearestPeg(node.x())

      const isValid =
        toPeg !== null &&
        toPeg !== this.fromPeg &&
        this.canMove(disk, toPeg)

      if (isValid) {
        this.move(disk, this.fromPeg, toPeg)
        this.moves++
        this.layout()
      } else {
        disk.x = disk.oldX
        disk.y = disk.oldY

        node.position({
          x: disk.oldX,
          y: disk.oldY
        })

        node.getLayer().batchDraw()
        this.renderKey++
      }

      this.fromPeg = null
    },

    getNearestPeg(x) {
      let nearestPeg = null
      let minDistance = Infinity
      const dropRange = this.stageConfig.width < 480 ? 45 : 80

      this.pegs.forEach(peg => {
        const distance = Math.abs(x - peg.x)

        if (distance < minDistance) {
          minDistance = distance
          nearestPeg = peg.id
        }
      })

      return minDistance <= dropRange ? nearestPeg : null
    },

    canMove(disk, pegIndex) {
      const stack = this.stacks[pegIndex]

      if (!stack.length) return true

      const topDiskId = stack[stack.length - 1]
      const topDisk = this.disks.find(d => d.id === topDiskId)

      return disk.size < topDisk.size
    },

    move(disk, fromPeg, toPeg) {
      this.stacks[fromPeg].pop()
      this.stacks[toPeg].push(disk.id)
      disk.peg = toPeg
    }
  }
}
</script>

<style scoped>
.hanoi {
  padding: 12px;
  text-align: center;
  background: #e2e8f0;
  min-height: 100vh;
  overflow-x: hidden;
}

.hanoi h2 {
  margin: 8px 0 12px;
}

.info {
  margin-bottom: 12px;
  display: flex;
  justify-content: center;
  gap: 8px 12px;
  align-items: center;
  flex-wrap: wrap;
}

.stage-wrap {
  width: 100%;
  display: flex;
  justify-content: center;
}

select {
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
}

button {
  padding: 6px 14px;
  border: none;
  border-radius: 8px;
  background: #2563eb;
  color: white;
  cursor: pointer;
}

.win {
  margin: 10px 0 16px;
  color: #16a34a;
  font-weight: bold;
  font-size: 18px;
}

@media (max-width: 480px) {
  .hanoi h2 {
    font-size: 18px;
  }

  .info {
    font-size: 13px;
  }

  button,
  select {
    height: 34px;
  }
}
</style>